using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseForeheadCandidate {
 static float S(float a,float b,float v){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,v));}
 public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab"));go.GetComponent<Animator>().enabled=false;go.GetComponent<LODGroup>().ForceLOD(0);RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(go);var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var m=r.sharedMesh;var p=m.vertices.Select(r.transform.TransformPoint).ToArray();var uv=m.uv;var tri=m.GetTriangles(0);var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);t.LoadImage(File.ReadAllBytes(NurseVisualOptimization.Folder+"/Atlas_Normal.png"));int n=t.width;var c=t.GetPixels();int changed=0;
 for(int k=0;k<tri.Length;k+=3){int a=tri[k],b=tri[k+1],d=tri[k+2];if(Mathf.Max(p[a].y,Mathf.Max(p[b].y,p[d].y))<1.64f)continue;var A=uv[a]*n;var B=uv[b]*n;var C=uv[d]*n;float det=(B.y-C.y)*(A.x-C.x)+(C.x-B.x)*(A.y-C.y);if(Mathf.Abs(det)<1e-8f)continue;
 for(int y=Mathf.Max(0,(int)Mathf.Min(A.y,Mathf.Min(B.y,C.y)));y<=Mathf.Min(n-1,Mathf.CeilToInt(Mathf.Max(A.y,Mathf.Max(B.y,C.y))));y++)for(int x=Mathf.Max(0,(int)Mathf.Min(A.x,Mathf.Min(B.x,C.x)));x<=Mathf.Min(n-1,Mathf.CeilToInt(Mathf.Max(A.x,Mathf.Max(B.x,C.x))));x++){float u=((B.y-C.y)*(x+.5f-C.x)+(C.x-B.x)*(y+.5f-C.y))/det;float v=((C.y-A.y)*(x+.5f-C.x)+(A.x-C.x)*(y+.5f-C.y))/det;float w=1-u-v;if(u<0||v<0||w<0)continue;var pos=p[a]*u+p[b]*v+p[d]*w;float amount=S(1.65f,1.675f,pos.y)*(1-S(1.705f,1.72f,pos.y))*(1-S(.05f,.075f,Mathf.Abs(pos.x)))*S(.025f,.045f,pos.z);if(amount<.001f)continue;int i=y*n+x;var normal=new Vector3(c[i].r*2-1,c[i].g*2-1,c[i].b*2-1).normalized;normal=Vector3.Lerp(normal,Vector3.forward,amount*.90f).normalized;c[i]=new Color(normal.x*.5f+.5f,normal.y*.5f+.5f,normal.z*.5f+.5f,1);changed++;}}
 t.SetPixels(c);t.Apply(); // runtime normal texture uses Unity's packed normal layout
 var packed=new Texture2D(n,n,TextureFormat.RGBA32,false,true);packed.SetPixels(c.Select(v=>new Color(1,v.g,1,v.r)).ToArray());packed.Apply();foreach(var renderer in go.GetComponentsInChildren<SkinnedMeshRenderer>(true))renderer.sharedMaterials=renderer.sharedMaterials.Select(old=>{var material=new Material(old);if(material.HasProperty("_Normal"))material.SetTexture("_Normal",packed);return material;}).ToArray();NurseVisualOptimization.Render(go,"ForeheadCandidate",0,true,true);File.WriteAllText(NurseVisualOptimization.Out+"/forehead-candidate.txt","Temporary map only; no assets modified. Local forehead normal attenuation, texels="+changed+". Geometry/UV/weights/rig/colliders unchanged.");}
}
